WITH enriched AS (SELECT *, NTILE(4) OVER (PARTITION BY product_id ORDER BY units DESC, id) AS units_bucket, DENSE_RANK() OVER (ORDER BY units DESC NULLS LAST) AS units_dense_rank, ROUND(revenue / SUM(revenue) OVER (PARTITION BY store_id), 4) AS revenue_share, SUM(revenue) OVER (PARTITION BY product_id ORDER BY revenue, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_revenue FROM store_sales) SELECT s.id, s.store_id, s.product_id, s.sale_date, s.units, s.revenue, s.units_bucket, s.units_dense_rank, s.revenue_share, (SELECT MAX(i2.quantity) FROM inventory i2 WHERE i2.store_id = s.store_id) AS max_inventory_quantity FROM enriched s;
